#include <TMB.hpp>
template<class Type> Type objective_function<Type>::operator()(){DATA_MATRIX(y);DATA_VECTOR(gh_nodes);DATA_VECTOR(gh_weights);PARAMETER_VECTOR(beta);PARAMETER_VECTOR(loading_free);int n=y.rows(),T=y.cols(),H=gh_nodes.size();matrix<Type>L(T,2);L.setZero();L(0,0)=exp(loading_free(0));L(1,0)=loading_free(1);L(1,1)=exp(loading_free(2));int k=3;for(int t=2;t<T;t++){L(t,0)=loading_free(k++);L(t,1)=loading_free(k++);}Type nll=0;for(int i=0;i<n;i++){Type a=0;bool first=true;for(int r=0;r<H;r++)for(int s=0;s<H;s++){Type z=log(gh_weights(r))+log(gh_weights(s));for(int t=0;t<T;t++){Type eta=beta(t)+L(t,0)*gh_nodes(r)+L(t,1)*gh_nodes(s);z+=y(i,t)*eta-logspace_add(Type(0),eta);}if(first){a=z;first=false;}else a=logspace_add(a,z);}nll-=a;}return nll;}
